/// Compute the exponential backoff duration for a given retry attempt.
/// Returns None if the maximum retry count is exceeded.
fn compute_backoff(attempt_count: u32, max_retries: u32) -> Option<Duration> {
    // Base slot time in milliseconds
    let base_millis: u64 = 100;
    if attempt_count >= max_retries {
        return None;
    }
    let factor = 2_u64.pow(attempt_count);
    Some(Duration::from_millis(base_millis * factor))
}

